const config=window.PORTFOLIO;
document.querySelectorAll('[data-name]').forEach(function(el){el.textContent=config.name});
document.title=config.name+' — Developer & Visual Creator';
document.getElementById('year').textContent=new Date().getFullYear();
const mobileMenu=document.getElementById('mobile-menu'),menuToggle=document.getElementById('menu-toggle');
function setMenu(open){mobileMenu.classList.toggle('open',open);mobileMenu.setAttribute('aria-hidden',String(!open));menuToggle.setAttribute('aria-expanded',String(open));document.body.classList.toggle('menu-open',open)}
menuToggle.addEventListener('click',function(){setMenu(true)});
document.getElementById('menu-close').addEventListener('click',function(){setMenu(false)});
mobileMenu.querySelectorAll('a').forEach(function(link){link.addEventListener('click',function(){setMenu(false)})});
const dialogs=document.querySelectorAll('dialog');
function openDialog(dialog){dialog.showModal();document.body.classList.add('modal-open')}
dialogs.forEach(function(dialog){dialog.querySelector('.close-dialog').addEventListener('click',function(){dialog.close()});dialog.addEventListener('close',function(){document.body.classList.remove('modal-open')});dialog.addEventListener('click',function(event){if(event.target===dialog)dialog.close()})});
document.querySelectorAll('.filter').forEach(function(button){button.addEventListener('click',function(){document.querySelectorAll('.filter').forEach(function(other){const active=other===button;other.classList.toggle('active',active);other.setAttribute('aria-pressed',String(active))});document.querySelectorAll('.project-card').forEach(function(card){card.hidden=button.dataset.filter!=='all'&&card.dataset.category!==button.dataset.filter})})});
const projectDialog=document.getElementById('project-dialog');
document.querySelectorAll('[data-project]').forEach(function(button){button.addEventListener('click',function(){const project=config.projects[Number(button.dataset.project)],image=document.getElementById('dialog-image');image.src=project.image;image.alt=project.title+' project screenshot';document.getElementById('dialog-title').textContent=project.title;document.getElementById('dialog-category').textContent=project.category;document.getElementById('dialog-description').textContent=project.description;const list=document.getElementById('dialog-deliverables');list.replaceChildren();project.deliverables.forEach(function(text){const item=document.createElement('li');item.textContent=text;list.append(item)});const link=document.getElementById('project-link');link.href=project.url;link.textContent=project.cta;openDialog(projectDialog)})});
document.querySelector('.dialog-contact').addEventListener('click',function(){projectDialog.close()});
document.getElementById('inquiry-form').addEventListener('submit',function(event){event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;const values=new FormData(form),name=String(values.get('name')).trim(),email=String(values.get('email')).trim(),message=String(values.get('message')).trim();const brief='PROJECT INQUIRY\n\nName: '+name+'\nEmail: '+email+'\nServices: '+(values.getAll('service').join(', ')||'Let’s discuss')+'\n\nProject details:\n'+message;window.location.href='mailto:'+config.email.trim()+'?subject='+encodeURIComponent('Project inquiry from '+name)+'&body='+encodeURIComponent(brief);document.getElementById('form-status').textContent='Your email app should open. Review the message and send when ready.'});
